<?php require_once '../config/auth.php'; exigirPerfil(['Administrador','Técnico','Trabalhador']); require_once '../config/conexao.php';$id=(int)($_GET['id']??0);$d=['cliente_id'=>'','tipo'=>'','marca'=>'','modelo'=>'','numero_serie'=>'','descricao'=>''];$erro='';if($id){$st=$conn->prepare('SELECT * FROM equipamentos WHERE id=?');$st->bind_param('i',$id);$st->execute();$x=$st->get_result()->fetch_assoc();if(!$x)exit('Equipamento não encontrado.');$d=array_merge($d,$x);}$clientes=$conn->query('SELECT id,nome FROM clientes ORDER BY nome');if($_SERVER['REQUEST_METHOD']==='POST'){$d=array_merge($d,$_POST);$cliente=(int)($_POST['cliente_id']??0);$tipo=trim($_POST['tipo']??'');$marca=trim($_POST['marca']??'');$modelo=trim($_POST['modelo']??'');$serie=trim($_POST['numero_serie']??'');$desc=trim($_POST['descricao']??'');if(!$cliente||!$tipo)$erro='Selecione um cliente e informe o tipo do equipamento.';else{if($id){$st=$conn->prepare('UPDATE equipamentos SET cliente_id=?,tipo=?,marca=?,modelo=?,numero_serie=?,descricao=? WHERE id=?');$st->bind_param('isssssi',$cliente,$tipo,$marca,$modelo,$serie,$desc,$id);}else{$st=$conn->prepare('INSERT INTO equipamentos(cliente_id,tipo,marca,modelo,numero_serie,descricao) VALUES(?,?,?,?,?,?)');$st->bind_param('isssss',$cliente,$tipo,$marca,$modelo,$serie,$desc);}if($st->execute()){header('Location: listar.php');exit;}else $erro='Não foi possível salvar o equipamento.';}}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Equipamento | HelpTech</title><link rel="stylesheet" href="../css/style.css"></head><body><header class="topbar"><a class="brand" href="../dashboard.php"><span class="brand-mark">H</span>HelpTech</a><nav class="top-actions"><a href="../logout.php">Sair ↗</a></nav></header><main class="container form-container"><div class="eyebrow">Cadastros / Equipamentos</div><h1><?= $id?'Editar equipamento':'Novo equipamento' ?></h1><p class="subtitle">Associe o equipamento ao cliente responsável.</p><section class="form-card"><?php if($erro):?><div class="alert error"><?= h($erro) ?></div><?php endif;?><?php if(!$clientes||$clientes->num_rows===0):?><div class="alert error">Cadastre um cliente antes de cadastrar equipamentos.</div><a class="button" href="../clientes/cadastrar.php">Cadastrar cliente</a><?php else:?><form method="post"><div class="form-grid"><div class="field full"><label>Cliente *</label><select name="cliente_id" required><option value="">Selecione o cliente</option><?php while($c=$clientes->fetch_assoc()):?><option value="<?= (int)$c['id'] ?>" <?= (int)$d['cliente_id']===(int)$c['id']?'selected':'' ?>><?= h($c['nome']) ?></option><?php endwhile;?></select></div><div class="field"><label>Tipo *</label><input name="tipo" required value="<?= h($d['tipo']) ?>" placeholder="Notebook, desktop, impressora..."></div><div class="field"><label>Marca</label><input name="marca" value="<?= h($d['marca']) ?>"></div><div class="field"><label>Modelo</label><input name="modelo" value="<?= h($d['modelo']) ?>"></div><div class="field"><label>Número de série</label><input name="numero_serie" value="<?= h($d['numero_serie']) ?>"></div><div class="field full"><label>Descrição / observações</label><textarea name="descricao"><?= h($d['descricao']) ?></textarea></div></div><div class="form-actions"><button>Salvar equipamento</button><a class="button secondary" href="listar.php">Cancelar</a></div></form><?php endif;?></section></main></body></html>